using System;using System.Collections.Generic;using System.Linq;using System.Globalization;
class Student{public string Name;public double GPA;public string Major;public Student(string name,double gpa,string major){Name=name;GPA=gpa;Major=major;}}
class Program{static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;var students=new List<Student>{new Student("An",8.5,"CS"),new Student("Binh",9.2,"CS"),new Student("Chi",7.8,"Math"),new Student("Duy",6.5,"Math"),new Student("Em",9.0,"CS")};var q=from s in students where s.Major=="CS"&&s.GPA>=8.0 orderby s.GPA descending select s.Name;Console.WriteLine(string.Join(",",q));}}

